        Outcome = strcat(LogonType, " · ", iff(ActionType == "LogonSuccess", "success", "failure"))
),
(
    IdentityLogonEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where IPAddress == Value
    | project Timestamp, Target = iff(isnotempty(TargetDeviceName), tolower(TargetDeviceName), strcat(tolower(DestinationDeviceName), " · validation")),
        Outcome = strcat(Protocol, " · ", iff(ActionType == "LogonSuccess", "success", "failure"))
),
(
    DeviceNetworkEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
