(
    DeviceLogonEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where AccountName =~ ValueSam
    | project Timestamp, Serie = strcat("Defender · ", LogonType, " · ", iff(ActionType == "LogonSuccess", "success", "failure"))
),
(
    IdentityLogonEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where AccountUpn =~ ValueUpn or AccountName =~ ValueSam
    | project Timestamp, Serie = strcat("Defender for Identity · ", Protocol, " · ", iff(ActionType == "LogonSuccess", "success", "failure"))
)
| summarize Events = count() by bin(Timestamp, 1h), Serie
| render timechart

