let UserIds = _Signins(StartTimestamp - 1d, EndTimestamp, "", ValueUpn) | where isnotempty(UserId) | distinct UserId;
union isfuzzy=true
(
    _Signins(StartTimestamp, EndTimestamp, "", ValueUpn)
    | project Timestamp, Source = strcat("Entra ID ", SignInType), Host = DeviceName, Account = tolower(UserPrincipalName),
        Action = iff(Succeeded, "Successful sign-in", strcat("Failed sign-in ", ResultType)),
        Detail = strcat(AppDisplayName, " · ", IPAddress, " · ", Location, " · ", OperatingSystem, " ", Browser)
),
(
    CloudAppEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where tostring(RawEventData.UserId) =~ ValueUpn
    | project Timestamp, Source = strcat("CloudAppEvents (", Application, ")"), Host = "", Account = ValueUpn, Action = ActionType,
        Detail = strcat(ObjectName, " · ", IPAddress, " · ", CountryCode)
),
(
    DeviceLogonEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where AccountName =~ ValueSam
    | project Timestamp, Source = "DeviceLogonEvents", Host = tolower(DeviceName), Account = tolower(AccountName),
        Action = strcat(ActionType, " ", LogonType), Detail = strcat(RemoteIP, " ", RemoteDeviceName)
),
(
    IdentityLogonEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where AccountUpn =~ ValueUpn or AccountName =~ ValueSam
    | project Timestamp, Source = "IdentityLogonEvents", Host = tolower(TargetDeviceName), Account = ValueSam,
        Action = strcat(ActionType, " ", Protocol, " ", LogonType),
        Detail = strcat("from ", coalesce(DeviceName, IPAddress), " · validated by ", DestinationDeviceName, " · ", FailureReason)
),
(
    // Defender for Identity: directory changes made by the account or targeting it (password, groups, state)
    IdentityDirectoryEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where AccountUpn =~ ValueUpn or AccountName =~ ValueSam or TargetAccountUpn =~ ValueUpn
    | extend IsTarget = TargetAccountUpn =~ ValueUpn
    | project Timestamp, Source = "IdentityDirectoryEvents", Host = tolower(TargetDeviceName), Account = ValueSam,
        Action = strcat(ActionType, iff(IsTarget, " (as target)", "")),
        Detail = strcat(iff(IsTarget, strcat("by ", coalesce(AccountUpn, AccountName)), strcat("target ", coalesce(TargetAccountUpn, TargetAccountDisplayName, TargetDeviceName))),
            " · ", Application, " · from ", coalesce(DeviceName, IPAddress), " · ", substring(tostring(AdditionalFields), 0, 200))
),
(
    // Defender for Identity: reconnaissance queries sent by the account (LDAP, SAMR, DNS, SMB)
    IdentityQueryEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where AccountUpn =~ ValueUpn or AccountName =~ ValueSam
    | project Timestamp, Source = "IdentityQueryEvents", Host = tolower(DeviceName), Account = ValueSam,
        Action = strcat(ActionType, " ", Protocol, " ", QueryType),
        Detail = strcat(QueryTarget, " · to ", DestinationDeviceName, " · ", substring(Query, 0, 200))
),
(
    UrlClickEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where AccountUpn =~ ValueUpn
    | project Timestamp, Source = "UrlClickEvents", Host = "", Account = tolower(AccountUpn),
        Action = strcat("Click ", ActionType), Detail = Url
)
| sort by Timestamp asc

