    | project TimeGenerated, AccountUpn = tolower(SourceUserName), Kind = "proxy", ActionType = DeviceAction, IsClickedThrough = false,
        Url = coalesce(RequestURL, DestinationHostName), Workload = "", Ip = SourceIP, Device = tolower(SourceHostName), Process = "",
        Source = strcat("CommonSecurityLog (", DeviceVendor, ")")
