    FirstClick = min(TimeGenerated), LastClick = max(TimeGenerated),
    Urls = make_set(Url, 10), Workloads = make_set_if(Workload, isnotempty(Workload)), IPs = make_set_if(Ip, isnotempty(Ip), 5),
