rules.queryDefender:
// [DM-P3] Devices and processes in contact with the domain — Pivot / Domain, URL
// sentinel-pivot-rules 0.2.0. Parameters: {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 10080) * 1m; // default: 7d
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 1440) * 1m; // default: 1d
let StartTimestamp = T0 - Before;
let EndTimestamp = T0 + After;
// Common URL / domain functions.
// _Host: host of a URL or a name (adds a scheme if missing so that parse_url works).
// _InDomain: true if the host is the domain or one of its subdomains.
let _Host = (u:string) { tolower(tostring(parse_url(iff(u contains "://", u, strcat("http://", u))).Host)) };
let _InDomain = (h:string, d:string) { isnotempty(d) and (h == d or h endswith strcat(".", d)) };
// URL and Domain indicators: ValueDomain is the URL host, or the value itself if it is a domain.
// @requires: web_functions
let ValueUrl = Value;
let ValueDomain = trim_end(@"\.", _Host(Value));
// Entity roles (devices, IPs, accounts): separates "where the event is logged" from "where the entity is used"
// and flags entities that skew a pivot (domain controller, NAT, proxy, service account...).
// Three combined sources:
// 1. automatic domain controller (DC) detection: hosts emitting 4768 (only a KDC does), LDAP targets seen by
//    Defender for Identity, devices accepting Kerberos connections (port 88) according to Defender for Endpoint;
// 2. Sentinel watchlist "EasyPivotRoles" (columns Entity, Type, Role, Note), template in watchlists/EasyPivotRoles.csv;
//    Type values (case-insensitive): Machine/Host/Device, IP/CIDR/Subnet, Account/User (French values still accepted);
// 3. accounts: IdentityInfo (Entra ID roles, privileged AD groups, service account, Defender for Identity tags)
//    and reserved names (machine account, system account, krbtgt, Entra Connect sync).
// Each function takes the reference time `at` and looks at the preceding day (14 days for IdentityInfo).
// "@sentinel-only" blocks are removed from the Defender XDR variant (tables missing in Defender).
//
// _HostKey(h): lowercase short name (FQDN, NetBIOS, machine account "PC01$" -> "pc01"); empty for an IP address.
let _HostKey = (h:string) {
    iff(isnotnull(parse_ipv4(h)) or h contains ":", "", tolower(tostring(split(trim_end(@"\$", trim(@"[\s\\]+", h)), ".")[0])))
};
// _SamOf(a): SAM name of an account, from "DOMAIN\name", "name@domain" or "name".
let _SamOf = (a:string) { tolower(tostring(split(tostring(split(a, "@")[0]), @"\")[-1])) };
// _Labeled(name, role): "dc01 [DC]", to annotate lists (make_set) without adding a column.
let _Labeled = (name:string, role:string) { iff(isempty(role), name, strcat(name, " [", role, "]")) };
// _JoinRoles(a, b): joins two role labels, skipping empty ones.
let _JoinRoles = (a:string, b:string) { strcat_array(set_difference(pack_array(a, b), dynamic([""])), ", ") };
// _AccountKind(SAM name): category inferred from the name alone.
let _AccountKind = (sam:string) {
    case(
        sam endswith "$", "Machine account",
        sam in ("system", "local system", "local service", "network service", "anonymous logon", "iusr", "-")
            or sam startswith "dwm-" or sam startswith "umfd-", "System account",
        sam == "krbtgt", "KDC account (krbtgt)",
        sam startswith "msol_" or sam startswith "sync_" or sam startswith "aad_" or sam startswith "adtoaadsyncserviceaccount",
            "Entra Connect sync",
        sam in ("administrator", "administrateur"), "Built-in administrator",
        "")
};
// _DcEvidence(at): devices (and IPs) that behave like domain controllers.
let _DcEvidence = (at:datetime) {
    union isfuzzy=true
    (
        datatable(Machine:string, Ip:string, Basis:string)[]
    ),
    (
        IdentityQueryEvents
        | where Timestamp between ((at - 1d) .. at)
        | where Protocol =~ "Ldap" and isnotempty(DestinationDeviceName)
        | summarize by DestinationDeviceName, DestinationIPAddress
        | project Machine = DestinationDeviceName, Ip = DestinationIPAddress, Basis = "LDAP target (Defender for Identity)"
    ),
    (
        DeviceNetworkEvents
        | where Timestamp between ((at - 1d) .. at)
        | where LocalPort == 88 and ActionType in ("InboundConnectionAccepted", "ListeningConnectionCreated")
        | summarize by DeviceName, LocalIP
        | project Machine = DeviceName, Ip = LocalIP, Basis = "Accepts Kerberos on port 88 (Defender for Endpoint)"
    )
};
// _MachineRoles(at): MachineKey (short name), MachineRole ("DC, File server"), MachineRoleBasis (evidence).
let _MachineRoles = (at:datetime) {
    union isfuzzy=true
    (
        datatable(MachineKey:string, Role:string, Basis:string)[]
    ),
    (
        _DcEvidence(at)
        | project MachineKey = _HostKey(Machine), Role = "DC", Basis
    ),
    (
        Watchlist
        | where WatchlistAlias =~ "EasyPivotRoles" and _DTItemType == "watchlist-item"
        | summarize arg_max(_DTTimestamp, _DTItemStatus, WatchlistItem) by _DTItemId
        | where _DTItemStatus != "Deleted"
        | where tolower(tostring(WatchlistItem.Type)) in ("machine", "host", "device", "serveur", "poste")
        | project MachineKey = _HostKey(tostring(WatchlistItem.Entity)), Role = tostring(WatchlistItem.Role),
            Basis = strcat("Watchlist EasyPivotRoles ", tostring(WatchlistItem.Note))
    )
    | where isnotempty(MachineKey) and isnotempty(Role)
    | summarize MachineRoles = make_set(Role), MachineRoleBasis = make_set(Basis, 5) by MachineKey
    | project MachineKey, MachineRole = strcat_array(MachineRoles, ", "), MachineRoleBasis
};
// _IpRoles(at): Ip (exact address or CIDR range), IpRole, IpRoleBasis.
let _IpRoles = (at:datetime) {
    union isfuzzy=true
    (
        datatable(Ip:string, Role:string, Basis:string)[]
    ),
    (
        _DcEvidence(at)
        | where isnotempty(Ip)
        | project Ip, Role = "DC", Basis
    ),
    (
        Watchlist
        | where WatchlistAlias =~ "EasyPivotRoles" and _DTItemType == "watchlist-item"
        | summarize arg_max(_DTTimestamp, _DTItemStatus, WatchlistItem) by _DTItemId
        | where _DTItemStatus != "Deleted"
        | where tolower(tostring(WatchlistItem.Type)) in ("ip", "plage", "cidr", "subnet", "réseau")
        | project Ip = trim(@"\s", tostring(WatchlistItem.Entity)), Role = tostring(WatchlistItem.Role),
            Basis = strcat("Watchlist EasyPivotRoles ", tostring(WatchlistItem.Note))
    )
    | where isnotempty(Ip) and isnotempty(Role)
    | summarize IpRoles = make_set(Role), IpRoleBasis = make_set(Basis, 5) by Ip
    | project Ip, IpRole = strcat_array(IpRoles, ", "), IpRoleBasis
};
// _IpRoleOf(ip, at): known roles of an address, including membership in a watchlist CIDR range.
let _IpRoleOf = (ip:string, at:datetime) {
    toscalar(_IpRoles(at)
        | where Ip == ip or (Ip has "/" and ipv4_is_in_range(ip, Ip))
        | summarize Roles = strcat_array(make_set(IpRole), ", "))
};
// _AccountRoles(at): AccountKey (lowercase SAM name or UPN), AccountRole, AccountRoleBasis.
let _AccountRoles = (at:datetime) {
    union isfuzzy=true
    (
        datatable(AccountKey:string, Role:string, Basis:string)[]
    ),
    (
        IdentityInfo
        | where Timestamp between ((at - 14d) .. at)
        | extend Sam = tolower(coalesce(tostring(column_ifexists("SAMAccountName", "")), AccountName)),
            Upn = tolower(coalesce(tostring(column_ifexists("AccountUPN", "")), tostring(column_ifexists("AccountUpn", "")))),
            EntraRoles = tostring(column_ifexists("AssignedRoles", dynamic([]))),
            Groups = tostring(column_ifexists("GroupMembership", dynamic([]))),
            IsSvc = tobool(column_ifexists("IsServiceAccount", false)),
            IdTags = tostring(column_ifexists("Tags", ""))
        | where isnotempty(Sam)
        | summarize arg_max(Timestamp, Upn, EntraRoles, Groups, IsSvc, IdTags) by Sam
        | extend Roles = pack_array(
            iff(EntraRoles in ("", "[]", "null"), "", "Entra ID role assigned"),
            iff(Groups has_any ("Domain Admins", "Enterprise Admins", "Schema Admins", "Account Operators", "Backup Operators",
                    "Server Operators", "Admins du domaine", "Administrateurs de l'entreprise", "Administrateurs du schéma",
                    "Opérateurs de compte", "Opérateurs de sauvegarde", "Opérateurs de serveur"), "Privileged AD group", ""),
            iff(IsSvc, "Service account", ""),
            iff(IdTags has_any ("Sensitive", "Sensible"), "Sensitive account", ""),
            iff(IdTags has "Honeytoken", "Honeytoken account", ""))
        | mv-expand Role = Roles to typeof(string)
        | where isnotempty(Role)
        | mv-expand AccountKey = pack_array(Sam, Upn) to typeof(string)
        | project AccountKey, Role, Basis = "IdentityInfo"
    ),
    (
        Watchlist
        | where WatchlistAlias =~ "EasyPivotRoles" and _DTItemType == "watchlist-item"
        | summarize arg_max(_DTTimestamp, _DTItemStatus, WatchlistItem) by _DTItemId
        | where _DTItemStatus != "Deleted"
        | where tolower(tostring(WatchlistItem.Type)) in ("compte", "account", "user", "utilisateur")
        | extend Raw = tolower(trim(@"\s", tostring(WatchlistItem.Entity)))
        | mv-expand AccountKey = pack_array(Raw, _SamOf(Raw)) to typeof(string)
        | project AccountKey, Role = tostring(WatchlistItem.Role), Basis = strcat("Watchlist EasyPivotRoles ", tostring(WatchlistItem.Note))
    )
    | where isnotempty(AccountKey) and isnotempty(Role)
    | summarize AccountRoles = make_set(Role), AccountRoleBasis = make_set(Basis, 5) by AccountKey
    | project AccountKey, AccountRole = strcat_array(AccountRoles, ", "), AccountRoleBasis
};
// Sysmon events (Microsoft-Windows-Sysmon/Operational log) normalized, whatever the ingestion table:
// Event (Azure Monitor agent, EventData as XML) or WindowsEvent (event forwarding, EventData as JSON).
// Parameters: start, end, ids (EventIDs, empty = all), term (text pre-filter on event data and device name, empty = none).
// Sysmon columns (Image, CommandLine, ParentImage, User, Hashes, TargetFilename, ImageLoaded, TargetObject, Details,
// SourceIp, DestinationIp, DestinationPort, DestinationHostname, QueryName, QueryResults...) and derived columns:
// Contents (Zone.Identifier stream of event 15: HostUrl and ReferrerUrl of the download).
// ProcessFile, ParentFile, TargetFile (lowercase file names), UserSam, SHA256, SHA1, MD5, RegistryEventType, EventName.
// Sentinel-only fragment: removed from the Defender variant (rules call it inside @sentinel-only blocks).
// Returns nothing unless Sysmon is installed with a configuration that logs the requested EventIDs.

union isfuzzy=true
(
    DeviceNetworkEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where RemoteUrl has ValueDomain
    | where _InDomain(_Host(RemoteUrl), ValueDomain)
    | project Timestamp, Source = "DeviceNetworkEvents", DeviceName = tolower(DeviceName), Account = tolower(InitiatingProcessAccountName),
        Process = tolower(InitiatingProcessFileName), CommandLine = InitiatingProcessCommandLine, Evidence = strcat(RemoteUrl, " (", RemoteIP, ")")
),
(
    DeviceFileEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where FileOriginUrl has ValueDomain or FileOriginReferrerUrl has ValueDomain
    | where _InDomain(_Host(FileOriginUrl), ValueDomain) or _InDomain(_Host(FileOriginReferrerUrl), ValueDomain)
    | project Timestamp, Source = "DeviceFileEvents", DeviceName = tolower(DeviceName), Account = tolower(InitiatingProcessAccountName),
        Process = tolower(InitiatingProcessFileName), CommandLine = InitiatingProcessCommandLine,
        Evidence = strcat(FolderPath, " ← ", FileOriginUrl, " · SHA256 ", SHA256)
),
(
    DeviceProcessEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where ProcessCommandLine has ValueDomain
    | project Timestamp, Source = "DeviceProcessEvents", DeviceName = tolower(DeviceName), Account = tolower(AccountName),
        Process = tolower(FileName), CommandLine = ProcessCommandLine, Evidence = "Domain in the command line"
)
| summarize Events = count(), FirstSeen = min(Timestamp), LastSeen = max(Timestamp),
    Evidence = make_set(Evidence, 10), CommandLines = make_set(CommandLine, 5) by DeviceName, Account, Process, Source
| extend MachineKey = _HostKey(DeviceName)
| lookup kind=leftouter (_MachineRoles(EndTimestamp)) on MachineKey
| extend AccountKind = _AccountKind(_SamOf(Account))
| project-away MachineKey, MachineRoleBasis
| sort by FirstSeen asc

// [DM-P4] DNS resolutions and related IPs — Pivot / Domain, URL
// sentinel-pivot-rules 0.2.0. Parameters: {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 10080) * 1m; // default: 7d
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 1440) * 1m; // default: 1d
let StartTimestamp = T0 - Before;
let EndTimestamp = T0 + After;
// Common URL / domain functions.
// _Host: host of a URL or a name (adds a scheme if missing so that parse_url works).
// _InDomain: true if the host is the domain or one of its subdomains.
let _Host = (u:string) { tolower(tostring(parse_url(iff(u contains "://", u, strcat("http://", u))).Host)) };
let _InDomain = (h:string, d:string) { isnotempty(d) and (h == d or h endswith strcat(".", d)) };
// URL and Domain indicators: ValueDomain is the URL host, or the value itself if it is a domain.
// @requires: web_functions
let ValueUrl = Value;
let ValueDomain = trim_end(@"\.", _Host(Value));
// Sysmon events (Microsoft-Windows-Sysmon/Operational log) normalized, whatever the ingestion table:
// Event (Azure Monitor agent, EventData as XML) or WindowsEvent (event forwarding, EventData as JSON).
// Parameters: start, end, ids (EventIDs, empty = all), term (text pre-filter on event data and device name, empty = none).
// Sysmon columns (Image, CommandLine, ParentImage, User, Hashes, TargetFilename, ImageLoaded, TargetObject, Details,
// SourceIp, DestinationIp, DestinationPort, DestinationHostname, QueryName, QueryResults...) and derived columns:
// Contents (Zone.Identifier stream of event 15: HostUrl and ReferrerUrl of the download).
// ProcessFile, ParentFile, TargetFile (lowercase file names), UserSam, SHA256, SHA1, MD5, RegistryEventType, EventName.
// Sentinel-only fragment: removed from the Defender variant (rules call it inside @sentinel-only blocks).
// Returns nothing unless Sysmon is installed with a configuration that logs the requested EventIDs.

union isfuzzy=true
(
    DeviceEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where ActionType == "DnsQueryResponse"
    | where AdditionalFields has ValueDomain
    | extend AF = parse_json(tostring(AdditionalFields))
    | extend Query = tolower(trim_end(@"\.", tostring(AF.DnsQueryString)))
    | where _InDomain(Query, ValueDomain)
    | project Timestamp, Source = "DeviceEvents (DNS)", Query, Answer = tostring(AF.DnsQueryResult), Client = tolower(DeviceName)
),
(
    DeviceNetworkEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where RemoteUrl has ValueDomain
    | where _InDomain(_Host(RemoteUrl), ValueDomain)
    | project Timestamp, Source = "DeviceNetworkEvents", Query = _Host(RemoteUrl), Answer = RemoteIP, Client = tolower(DeviceName)
)
// Defender XDR: DnsEvents equivalent, DNS queries received by domain controllers (Defender for Identity, no response)
, (
    IdentityQueryEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where Protocol =~ "Dns" and QueryTarget has ValueDomain
    | extend Query = tolower(trim_end(@"\.", QueryTarget))
    | where _InDomain(Query, ValueDomain)
    | project Timestamp, Source = "IdentityQueryEvents (DNS)", Query, Answer = "", Client = tolower(coalesce(DeviceName, IPAddress))
)
| summarize Lookups = count(), FirstSeen = min(Timestamp), LastSeen = max(Timestamp),
    ClientCount = dcount(Client), Clients = make_set(Client, 20) by Source, Query, Answer
| sort by FirstSeen asc

// [DM-P5] Files downloaded from the domain — Pivot / Domain, URL
// sentinel-pivot-rules 0.2.0. Parameters: {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 10080) * 1m; // default: 7d
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 1440) * 1m; // default: 1d
let StartTimestamp = T0 - Before;
let EndTimestamp = T0 + After;
// Common URL / domain functions.
// _Host: host of a URL or a name (adds a scheme if missing so that parse_url works).
// _InDomain: true if the host is the domain or one of its subdomains.
let _Host = (u:string) { tolower(tostring(parse_url(iff(u contains "://", u, strcat("http://", u))).Host)) };
let _InDomain = (h:string, d:string) { isnotempty(d) and (h == d or h endswith strcat(".", d)) };
// URL and Domain indicators: ValueDomain is the URL host, or the value itself if it is a domain.
// @requires: web_functions
let ValueUrl = Value;
let ValueDomain = trim_end(@"\.", _Host(Value));
// Sysmon events (Microsoft-Windows-Sysmon/Operational log) normalized, whatever the ingestion table:
// Event (Azure Monitor agent, EventData as XML) or WindowsEvent (event forwarding, EventData as JSON).
// Parameters: start, end, ids (EventIDs, empty = all), term (text pre-filter on event data and device name, empty = none).
// Sysmon columns (Image, CommandLine, ParentImage, User, Hashes, TargetFilename, ImageLoaded, TargetObject, Details,
// SourceIp, DestinationIp, DestinationPort, DestinationHostname, QueryName, QueryResults...) and derived columns:
// Contents (Zone.Identifier stream of event 15: HostUrl and ReferrerUrl of the download).
// ProcessFile, ParentFile, TargetFile (lowercase file names), UserSam, SHA256, SHA1, MD5, RegistryEventType, EventName.
// Sentinel-only fragment: removed from the Defender variant (rules call it inside @sentinel-only blocks).
// Returns nothing unless Sysmon is installed with a configuration that logs the requested EventIDs.

union isfuzzy=true
(
    DeviceFileEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where FileOriginUrl has ValueDomain or FileOriginReferrerUrl has ValueDomain
    | extend ViaReferrer = not(_InDomain(_Host(FileOriginUrl), ValueDomain))
    | where not(ViaReferrer) or _InDomain(_Host(FileOriginReferrerUrl), ValueDomain)
    | project Timestamp, Hash = tolower(coalesce(SHA256, SHA1)), FileName, Where = tolower(DeviceName),
        Who = tolower(coalesce(InitiatingProcessAccountUpn, InitiatingProcessAccountName)),
        Url = iff(ViaReferrer, strcat(FileOriginUrl, " (referrer ", FileOriginReferrerUrl, ")"), FileOriginUrl),
        Via = InitiatingProcessFileName, Source = "DeviceFileEvents"
),
(
    EmailUrlInfo
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where UrlDomain has ValueDomain or Url has ValueDomain
    | where _InDomain(tolower(coalesce(UrlDomain, _Host(Url))), ValueDomain)
    | summarize Url = take_any(Url) by NetworkMessageId
    | join kind=inner (
        EmailAttachmentInfo
        | where Timestamp between (StartTimestamp .. EndTimestamp)
        | where isnotempty(SHA256)
        ) on NetworkMessageId
    | project Timestamp, Hash = tolower(SHA256), FileName, Where = tolower(RecipientEmailAddress), Who = tolower(SenderFromAddress),
        Url = strcat("Message link: ", Url), Via = "Attachment", Source = "EmailUrlInfo + EmailAttachmentInfo"
)
| where isnotempty(Hash)
| summarize FirstSeen = min(Timestamp), LastSeen = max(Timestamp), Events = count(), WhereCount = dcount(Where),
    MachinesOrRecipients = make_set(Where, 10), AccountsOrSenders = make_set_if(Who, isnotempty(Who), 10),
    FileNames = make_set(FileName, 5), Urls = make_set(Url, 5), WrittenBy = make_set(Via, 5), Sources = make_set(Source)
    by FileHash = Hash
| extend Executable = tostring(FileNames) matches regex @"(?i)\.(exe|dll|scr|ps1|js|jse|vbs|vbe|hta|bat|cmd|msi|lnk|iso|img|zip|7z|rar)\b"
| sort by Executable desc, WhereCount desc, FirstSeen asc
| project FileHash, FileNames, Executable, FirstSeen, LastSeen, Events, WhereCount, MachinesOrRecipients, AccountsOrSenders, Urls,
    WrittenBy, Sources

// [DM-T1] Domain timeline — Timeline / Domain, URL
// sentinel-pivot-rules 0.2.0. Parameters: {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 30) * 1m; // default: 30m
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 30) * 1m; // default: 30m
let StartTimestamp = T0 - Before;
let EndTimestamp = T0 + After;
// Common URL / domain functions.
// _Host: host of a URL or a name (adds a scheme if missing so that parse_url works).
// _InDomain: true if the host is the domain or one of its subdomains.
let _Host = (u:string) { tolower(tostring(parse_url(iff(u contains "://", u, strcat("http://", u))).Host)) };
let _InDomain = (h:string, d:string) { isnotempty(d) and (h == d or h endswith strcat(".", d)) };
// URL and Domain indicators: ValueDomain is the URL host, or the value itself if it is a domain.
// @requires: web_functions
let ValueUrl = Value;
let ValueDomain = trim_end(@"\.", _Host(Value));
// Sysmon events (Microsoft-Windows-Sysmon/Operational log) normalized, whatever the ingestion table:
// Event (Azure Monitor agent, EventData as XML) or WindowsEvent (event forwarding, EventData as JSON).
// Parameters: start, end, ids (EventIDs, empty = all), term (text pre-filter on event data and device name, empty = none).
// Sysmon columns (Image, CommandLine, ParentImage, User, Hashes, TargetFilename, ImageLoaded, TargetObject, Details,
// SourceIp, DestinationIp, DestinationPort, DestinationHostname, QueryName, QueryResults...) and derived columns:
// Contents (Zone.Identifier stream of event 15: HostUrl and ReferrerUrl of the download).
// ProcessFile, ParentFile, TargetFile (lowercase file names), UserSam, SHA256, SHA1, MD5, RegistryEventType, EventName.
// Sentinel-only fragment: removed from the Defender variant (rules call it inside @sentinel-only blocks).
// Returns nothing unless Sysmon is installed with a configuration that logs the requested EventIDs.

// All logs involving a domain, mapped to common columns: Timestamp, Source, Host, Account, Url, Action.
// Sources: UrlClickEvents, URLs in emails and Teams messages, network connections, origin of downloaded files,
// DNS (Windows DNS servers, ASIM, DNS responses seen by Defender for Endpoint, Sysmon 22), Sysmon 3 connections, proxy and firewall (CEF, ASIM web,
// Azure Firewall).
// @requires: web_functions, sysmon
let _DomainHits = (start:datetime, end:datetime, d:string) {
    union isfuzzy=true
    (
        UrlClickEvents
        | where Timestamp between (start .. end)
        | where Url has d
        | where _InDomain(_Host(Url), d)
        | project Timestamp, Source = "UrlClickEvents", Host = "", Account = tolower(AccountUpn), Url, Action = strcat("Click ", ActionType)
    ),
    (
        EmailUrlInfo
        | where Timestamp between (start .. end)
        | where UrlDomain has d
        | where _InDomain(tolower(UrlDomain), d)
        | join kind=leftouter (
            EmailEvents
            | where Timestamp between (start .. end)
            | project NetworkMessageId, RecipientEmailAddress
            ) on NetworkMessageId
        | project Timestamp, Source = "EmailUrlInfo", Host = "", Account = tolower(RecipientEmailAddress), Url, Action = strcat("URL in an email (", UrlLocation, ")")
    ),
    (
        MessageUrlInfo
        | where Timestamp between (start .. end)
        | where UrlDomain has d
        | where _InDomain(tolower(UrlDomain), d)
        | project Timestamp, Source = "MessageUrlInfo", Host = "", Account = "", Url, Action = "URL in a Teams message"
    ),
    (
        DeviceNetworkEvents
        | where Timestamp between (start .. end)
        | where RemoteUrl has d
        | where _InDomain(_Host(RemoteUrl), d)
        | project Timestamp, Source = "DeviceNetworkEvents", Host = tolower(DeviceName), Account = tolower(InitiatingProcessAccountName),
            Url = RemoteUrl, Action = strcat(ActionType, " · ", InitiatingProcessFileName)
    ),
    (
        DeviceFileEvents
        | where Timestamp between (start .. end)
        | where FileOriginUrl has d or FileOriginReferrerUrl has d
        | where _InDomain(_Host(FileOriginUrl), d) or _InDomain(_Host(FileOriginReferrerUrl), d)
        | project Timestamp, Source = "DeviceFileEvents", Host = tolower(DeviceName), Account = tolower(InitiatingProcessAccountName),
            Url = iff(_InDomain(_Host(FileOriginUrl), d), FileOriginUrl, FileOriginReferrerUrl), Action = strcat("Download ", FileName)
    ),
    (
        DeviceEvents
        | where Timestamp between (start .. end)
        | where ActionType == "DnsQueryResponse"
        | where AdditionalFields has d
        | extend Q = tolower(trim_end(@"\.", tostring(parse_json(tostring(AdditionalFields)).DnsQueryString)))
        | where _InDomain(Q, d)
        | project Timestamp, Source = "DeviceEvents (DNS)", Host = tolower(DeviceName), Account = tolower(InitiatingProcessAccountName),
            Url = Q, Action = strcat("DNS · ", InitiatingProcessFileName)
    )
};
// Entity roles (devices, IPs, accounts): separates "where the event is logged" from "where the entity is used"
// and flags entities that skew a pivot (domain controller, NAT, proxy, service account...).
// Three combined sources:
// 1. automatic domain controller (DC) detection: hosts emitting 4768 (only a KDC does), LDAP targets seen by
//    Defender for Identity, devices accepting Kerberos connections (port 88) according to Defender for Endpoint;
// 2. Sentinel watchlist "EasyPivotRoles" (columns Entity, Type, Role, Note), template in watchlists/EasyPivotRoles.csv;
//    Type values (case-insensitive): Machine/Host/Device, IP/CIDR/Subnet, Account/User (French values still accepted);
// 3. accounts: IdentityInfo (Entra ID roles, privileged AD groups, service account, Defender for Identity tags)
//    and reserved names (machine account, system account, krbtgt, Entra Connect sync).
// Each function takes the reference time `at` and looks at the preceding day (14 days for IdentityInfo).
// "@sentinel-only" blocks are removed from the Defender XDR variant (tables missing in Defender).
//
// _HostKey(h): lowercase short name (FQDN, NetBIOS, machine account "PC01$" -> "pc01"); empty for an IP address.
let _HostKey = (h:string) {
    iff(isnotnull(parse_ipv4(h)) or h contains ":", "", tolower(tostring(split(trim_end(@"\$", trim(@"[\s\\]+", h)), ".")[0])))
};
// _SamOf(a): SAM name of an account, from "DOMAIN\name", "name@domain" or "name".
let _SamOf = (a:string) { tolower(tostring(split(tostring(split(a, "@")[0]), @"\")[-1])) };
// _Labeled(name, role): "dc01 [DC]", to annotate lists (make_set) without adding a column.
let _Labeled = (name:string, role:string) { iff(isempty(role), name, strcat(name, " [", role, "]")) };
// _JoinRoles(a, b): joins two role labels, skipping empty ones.
let _JoinRoles = (a:string, b:string) { strcat_array(set_difference(pack_array(a, b), dynamic([""])), ", ") };
// _AccountKind(SAM name): category inferred from the name alone.
let _AccountKind = (sam:string) {
    case(
        sam endswith "$", "Machine account",
        sam in ("system", "local system", "local service", "network service", "anonymous logon", "iusr", "-")
            or sam startswith "dwm-" or sam startswith "umfd-", "System account",
        sam == "krbtgt", "KDC account (krbtgt)",
        sam startswith "msol_" or sam startswith "sync_" or sam startswith "aad_" or sam startswith "adtoaadsyncserviceaccount",
            "Entra Connect sync",
        sam in ("administrator", "administrateur"), "Built-in administrator",
        "")
};
// _DcEvidence(at): devices (and IPs) that behave like domain controllers.
let _DcEvidence = (at:datetime) {
    union isfuzzy=true
    (
        datatable(Machine:string, Ip:string, Basis:string)[]
    ),
    (
        IdentityQueryEvents
        | where Timestamp between ((at - 1d) .. at)
        | where Protocol =~ "Ldap" and isnotempty(DestinationDeviceName)
        | summarize by DestinationDeviceName, DestinationIPAddress
        | project Machine = DestinationDeviceName, Ip = DestinationIPAddress, Basis = "LDAP target (Defender for Identity)"
    ),
    (
        DeviceNetworkEvents
        | where Timestamp between ((at - 1d) .. at)
        | where LocalPort == 88 and ActionType in ("InboundConnectionAccepted", "ListeningConnectionCreated")
        | summarize by DeviceName, LocalIP
        | project Machine = DeviceName, Ip = LocalIP, Basis = "Accepts Kerberos on port 88 (Defender for Endpoint)"
    )
};
// _MachineRoles(at): MachineKey (short name), MachineRole ("DC, File server"), MachineRoleBasis (evidence).
let _MachineRoles = (at:datetime) {
    union isfuzzy=true
    (
        datatable(MachineKey:string, Role:string, Basis:string)[]
    ),
    (
        _DcEvidence(at)
        | project MachineKey = _HostKey(Machine), Role = "DC", Basis
    ),
    (
        Watchlist
        | where WatchlistAlias =~ "EasyPivotRoles" and _DTItemType == "watchlist-item"
        | summarize arg_max(_DTTimestamp, _DTItemStatus, WatchlistItem) by _DTItemId
        | where _DTItemStatus != "Deleted"
        | where tolower(tostring(WatchlistItem.Type)) in ("machine", "host", "device", "serveur", "poste")
        | project MachineKey = _HostKey(tostring(WatchlistItem.Entity)), Role = tostring(WatchlistItem.Role),
            Basis = strcat("Watchlist EasyPivotRoles ", tostring(WatchlistItem.Note))
    )
    | where isnotempty(MachineKey) and isnotempty(Role)
    | summarize MachineRoles = make_set(Role), MachineRoleBasis = make_set(Basis, 5) by MachineKey
    | project MachineKey, MachineRole = strcat_array(MachineRoles, ", "), MachineRoleBasis
};
// _IpRoles(at): Ip (exact address or CIDR range), IpRole, IpRoleBasis.
let _IpRoles = (at:datetime) {
    union isfuzzy=true
    (
        datatable(Ip:string, Role:string, Basis:string)[]
    ),
    (
        _DcEvidence(at)
        | where isnotempty(Ip)
        | project Ip, Role = "DC", Basis
    ),
    (
        Watchlist
        | where WatchlistAlias =~ "EasyPivotRoles" and _DTItemType == "watchlist-item"
        | summarize arg_max(_DTTimestamp, _DTItemStatus, WatchlistItem) by _DTItemId
        | where _DTItemStatus != "Deleted"
        | where tolower(tostring(WatchlistItem.Type)) in ("ip", "plage", "cidr", "subnet", "réseau")
        | project Ip = trim(@"\s", tostring(WatchlistItem.Entity)), Role = tostring(WatchlistItem.Role),
            Basis = strcat("Watchlist EasyPivotRoles ", tostring(WatchlistItem.Note))
    )
    | where isnotempty(Ip) and isnotempty(Role)
    | summarize IpRoles = make_set(Role), IpRoleBasis = make_set(Basis, 5) by Ip
    | project Ip, IpRole = strcat_array(IpRoles, ", "), IpRoleBasis
};
// _IpRoleOf(ip, at): known roles of an address, including membership in a watchlist CIDR range.
let _IpRoleOf = (ip:string, at:datetime) {
    toscalar(_IpRoles(at)
        | where Ip == ip or (Ip has "/" and ipv4_is_in_range(ip, Ip))
        | summarize Roles = strcat_array(make_set(IpRole), ", "))
};
// _AccountRoles(at): AccountKey (lowercase SAM name or UPN), AccountRole, AccountRoleBasis.
let _AccountRoles = (at:datetime) {
    union isfuzzy=true
    (
        datatable(AccountKey:string, Role:string, Basis:string)[]
    ),
    (
        IdentityInfo
        | where Timestamp between ((at - 14d) .. at)
        | extend Sam = tolower(coalesce(tostring(column_ifexists("SAMAccountName", "")), AccountName)),
            Upn = tolower(coalesce(tostring(column_ifexists("AccountUPN", "")), tostring(column_ifexists("AccountUpn", "")))),
            EntraRoles = tostring(column_ifexists("AssignedRoles", dynamic([]))),
            Groups = tostring(column_ifexists("GroupMembership", dynamic([]))),
            IsSvc = tobool(column_ifexists("IsServiceAccount", false)),
            IdTags = tostring(column_ifexists("Tags", ""))
        | where isnotempty(Sam)
        | summarize arg_max(Timestamp, Upn, EntraRoles, Groups, IsSvc, IdTags) by Sam
        | extend Roles = pack_array(
            iff(EntraRoles in ("", "[]", "null"), "", "Entra ID role assigned"),
            iff(Groups has_any ("Domain Admins", "Enterprise Admins", "Schema Admins", "Account Operators", "Backup Operators",
                    "Server Operators", "Admins du domaine", "Administrateurs de l'entreprise", "Administrateurs du schéma",
                    "Opérateurs de compte", "Opérateurs de sauvegarde", "Opérateurs de serveur"), "Privileged AD group", ""),
            iff(IsSvc, "Service account", ""),
            iff(IdTags has_any ("Sensitive", "Sensible"), "Sensitive account", ""),
            iff(IdTags has "Honeytoken", "Honeytoken account", ""))
        | mv-expand Role = Roles to typeof(string)
        | where isnotempty(Role)
        | mv-expand AccountKey = pack_array(Sam, Upn) to typeof(string)
        | project AccountKey, Role, Basis = "IdentityInfo"
    ),
    (
        Watchlist
        | where WatchlistAlias =~ "EasyPivotRoles" and _DTItemType == "watchlist-item"
        | summarize arg_max(_DTTimestamp, _DTItemStatus, WatchlistItem) by _DTItemId
        | where _DTItemStatus != "Deleted"
        | where tolower(tostring(WatchlistItem.Type)) in ("compte", "account", "user", "utilisateur")
        | extend Raw = tolower(trim(@"\s", tostring(WatchlistItem.Entity)))
        | mv-expand AccountKey = pack_array(Raw, _SamOf(Raw)) to typeof(string)
        | project AccountKey, Role = tostring(WatchlistItem.Role), Basis = strcat("Watchlist EasyPivotRoles ", tostring(WatchlistItem.Note))
    )
    | where isnotempty(AccountKey) and isnotempty(Role)
    | summarize AccountRoles = make_set(Role), AccountRoleBasis = make_set(Basis, 5) by AccountKey
    | project AccountKey, AccountRole = strcat_array(AccountRoles, ", "), AccountRoleBasis
};
union isfuzzy=true
(
    _DomainHits(StartTimestamp, EndTimestamp, ValueDomain)
    | project Timestamp, Source, Host, Account, Action, Detail = Url
),
(
    DeviceProcessEvents
    | where Timestamp between (StartTimestamp .. EndTimestamp)
    | where ProcessCommandLine has ValueDomain
    | project Timestamp, Source = "DeviceProcessEvents", Host = tolower(DeviceName), Account = tolower(AccountName),
        Action = strcat("Process ", FileName), Detail = strcat(InitiatingProcessFileName, " → ", ProcessCommandLine)
)
| extend MachineKey = _HostKey(Host)
| lookup kind=leftouter (_MachineRoles(EndTimestamp)) on MachineKey
| extend Host = _Labeled(Host, MachineRole)
| project-away MachineKey, MachineRole, MachineRoleBasis
| sort by Timestamp asc

rules.query:
// [MC-S1] Device log volume per day and table — Statistics / Device
// sentinel-pivot-rules 0.2.0. Parameters: {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 10080) * 1m; // default: 7d
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 1440) * 1m; // default: 1d
let StartTimestamp = T0 - Before;
let EndTimestamp = T0 + After;
// Device indicator: case-insensitive match on the short name (before the first dot),
// to reconcile DeviceName (Defender FQDN) and Computer (Windows FQDN or NetBIOS).
let ValueHost = tolower(Value);
let ValueShort = tostring(split(ValueHost, ".")[0]);
let _IsHost = (h:string) { tolower(tostring(split(h, ".")[0])) == ValueShort };
union isfuzzy=true
(
    union isfuzzy=true withsource=Source DeviceProcessEvents, DeviceNetworkEvents, DeviceFileEvents, DeviceLogonEvents,
        DeviceRegistryEvents, DeviceEvents, DeviceImageLoadEvents, DeviceInfo, DeviceNetworkInfo
    | where TimeGenerated between (StartTimestamp .. EndTimestamp)
    | where DeviceName startswith ValueShort
    | where _IsHost(DeviceName)
    | project TimeGenerated, Source
),
// @sentinel-only:begin
(
    union isfuzzy=true withsource=Source SecurityEvent, WindowsEvent, Event, Syslog, Heartbeat
    | where TimeGenerated between (StartTimestamp .. EndTimestamp)
    | where Computer startswith ValueShort
    | where _IsHost(Computer)
    | project TimeGenerated, Source
),
// @sentinel-only:end
(
    union isfuzzy=true withsource=Source IdentityLogonEvents, IdentityQueryEvents, IdentityDirectoryEvents
    | where TimeGenerated between (StartTimestamp .. EndTimestamp)
    | where DeviceName has ValueShort or TargetDeviceName has ValueShort or DestinationDeviceName has ValueShort
    | where _IsHost(DeviceName) or _IsHost(TargetDeviceName) or _IsHost(DestinationDeviceName)
    | project TimeGenerated, Source
)
// @sentinel-only:begin
, (
    union isfuzzy=true withsource=Source ASimAuthenticationEventLogs, ASimProcessEventLogs, ASimFileEventLogs
    | where TimeGenerated between (StartTimestamp .. EndTimestamp)
    | where DvcHostname startswith ValueShort
    | where _IsHost(DvcHostname)
    | project TimeGenerated, Source
),
(
    CommonSecurityLog
    | where TimeGenerated between (StartTimestamp .. EndTimestamp)
    | where SourceHostName has ValueShort or DestinationHostName has ValueShort
    | where _IsHost(SourceHostName) or _IsHost(DestinationHostName)
    | project TimeGenerated, Source = strcat("CommonSecurityLog (", DeviceVendor, ")")
)
// @sentinel-only:end
| summarize Events = count() by bin(TimeGenerated, 1d), Source
| render timechart

