        FolderPath, SHA256, Company = ProcessVersionInfoCompanyName, OriginalName = ProcessVersionInfoOriginalFileName, Parent = InitiatingProcessFileName
)
| extend MachineKey = _HostKey(DeviceName)
| lookup kind=leftouter (_MachineRoles(EndTimestamp)) on MachineKey
| extend DeviceLabel = _Labeled(DeviceName, MachineRole)
| extend NormPath = _NormPath(FolderPath)
| summarize Executions = count(), Machines = dcount(DeviceName), Accounts = dcount(AccountName), ActiveDays = dcount(bin(Timestamp, 1d)),
    FirstSeen = min(Timestamp), LastSeen = max(Timestamp), Hashes = make_set_if(SHA256, isnotempty(SHA256), 10),
    Companies = make_set_if(Company, isnotempty(Company), 5), OriginalNames = make_set_if(OriginalName, isnotempty(OriginalName), 5),
