    | project TimeGenerated, Source = "Azure AD Graph", Identity = coalesce(UserId, ServicePrincipalId), AppOrigin = "", IPAddress = CallerIpAddress,
        Location = "", Operation = strcat(RequestMethod, " ", replace_regex(tostring(parse_url(RequestUri).Path), @"[0-9a-fA-F-]{36}", "{id}")),
